<?php
defined( 'ABSPATH' ) || exit;

/** گزارش جامع وضعیت مسیر همکاری و ظرفیت همه استادیارها */
class TA_Admin_Cooperation_Report {
    private array $modes = [
        'educational' => [ 'title'=>'همکاری آموزشی', 'name'=>'همراهِ آموزنده', 'count'=>22, 'score'=>35 ],
        'development' => [ 'title'=>'همکاری توسعه‌محور', 'name'=>'همراهِ سازنده', 'count'=>15, 'score'=>20 ],
        'capacity' => [ 'title'=>'همکاری ظرفیت‌محور', 'name'=>'همراهِ برازنده', 'count'=>32, 'score'=>57 ],
        'professional' => [ 'title'=>'نویسندگی حرفه‌ای', 'name'=>'همکاری خودکار', 'count'=>0, 'score'=>0 ],
        'critique' => [ 'title'=>'نقد اثر', 'name'=>'همکاری خودکار', 'count'=>0, 'score'=>0 ],
        'professional_critique' => [ 'title'=>'نویسندگی حرفه‌ای و نقد اثر', 'name'=>'همکاری خودکار', 'count'=>0, 'score'=>0 ],
    ];
    private array $courses = [ 'creative'=>'خلاق', 'basic_writing'=>'پایه', 'intro'=>'مقدماتی', 'advanced'=>'پیشرفته', 'professional'=>'حرفه‌ای', 'ladder'=>'نردبان حرفه‌ای', 'critique'=>'نقد اثر' ];
    private static bool $hooked = false;
    public function __construct() {
        if ( ! self::$hooked ) { add_action( 'wp_ajax_ta_admin_delete_report_capacity', [ $this, 'ajax_delete_capacity' ] ); self::$hooked = true; }
    }
    public function ajax_delete_capacity(): void {
        check_ajax_referer( 'ta_admin_cooperation_report', 'nonce' );
        if ( ! current_user_can( 'manage_options' ) ) wp_send_json_error( [ 'message' => 'دسترسی غیرمجاز.' ], 403 );
        $id = absint( $_POST['capacity_id'] ?? 0 );
        if ( ! $id ) wp_send_json_error( [ 'message' => 'شناسه ظرفیت نامعتبر است.' ] );
        $cap = TA_Database::get_row( 'SELECT * FROM ' . TA_Database::table('capacities') . ' WHERE id = %d', [ $id ] );
        if ( ! $cap ) wp_send_json_error( [ 'message' => 'ردیف ظرفیت پیدا نشد.' ] );
        if ( (int) $cap->used_capacity > 0 ) wp_send_json_error( [ 'message' => 'ظرفیت استفاده‌شده قابل حذف نیست.' ] );
        global $wpdb;
        $groups = $wpdb->get_var( $wpdb->prepare( 'SELECT COUNT(*) FROM ' . TA_Database::table('groups') . ' WHERE capacity_id = %d', [ $id ] ) );
        if ( (int) $groups > 0 ) wp_send_json_error( [ 'message' => 'این ظرفیت دارای گروه است و ابتدا باید گروه آن مدیریت شود.' ] );
        $deleted = TA_Database::delete( 'ta_capacities', [ 'id' => $id ] );
        if ( false === $deleted ) wp_send_json_error( [ 'message' => 'حذف ردیف ظرفیت انجام نشد.' ] );
        $cooperation_key = 'ta_cooperation_' . (int) $cap->ta_id . '_' . (int) $cap->term_id;
        $cooperation = get_option( $cooperation_key, [] );
        if ( is_array( $cooperation ) && in_array( $cooperation['mode'] ?? '', [ 'educational', 'development', 'capacity' ], true ) ) {
            $cooperation['status'] = 'incomplete';
            $cooperation['status_message'] = 'با حذف ظرفیت، حداقل شرایط این همکاری دیگر برقرار نیست؛ لطفاً ظرفیت‌ها را اصلاح کنید.';
            update_option( $cooperation_key, $cooperation, false );
        }
        wp_send_json_success( [ 'id' => $id, 'message' => 'ردیف ظرفیت حذف شد و وضعیت همکاری بررسی شد.' ] );
    }
    public function render(): void {
        if ( isset( $_GET['ta_export_cooperation_report'] ) ) { $this->export_csv(); return; }
        $terms = TA_Database::get_results( 'SELECT * FROM ' . TA_Database::table('terms') . ' ORDER BY created_at DESC, id DESC' );
        $term_id = absint( $_GET['term_id'] ?? 0 ); if ( ! $term_id && ! empty($terms) ) $term_id=(int)$terms[0]->id;
        $mode_filter = sanitize_key( $_GET['mode'] ?? 'all' ); $search = sanitize_text_field( $_GET['s'] ?? '' );
        $rows = $this->build_rows( $term_id );
        if ( $mode_filter !== 'all' ) $rows = array_filter($rows, static fn($r)=>$r['mode']===$mode_filter);
        if ( $search !== '' ) $rows = array_filter($rows, static fn($r)=>mb_stripos($r['name'].' '.$r['code'],$search)!==false);
        $total=count($rows); $selected=count(array_filter($rows,static fn($r)=>$r['mode'])); $eligible=count(array_filter($rows,static fn($r)=>$r['eligible'])); $capacity_total=array_sum(array_column($rows,'capacity_total')); $capacity_used=array_sum(array_column($rows,'capacity_used'));
        $export_url=wp_nonce_url(add_query_arg(['page'=>'ta-admin-cooperation-report','ta_export_cooperation_report'=>1,'term_id'=>$term_id]),'ta_export_cooperation_report');
        ?>
        <div class="wrap ta-admin-coop-report" dir="rtl"><div class="tacr-head"><div><span>داشبورد مدیریتی</span><h1>گزارش جامع همکاری و ظرفیت</h1><p>نمای کامل وضعیت انتخاب مسیر همکاری، ظرفیت‌های ثبت‌شده، شروط بار آموزشی و تعهدهای همه استادیارها.</p></div><a class="tacr-export" href="<?= esc_url($export_url) ?>">⬇ دریافت CSV</a></div>
        <form class="tacr-filters" method="get"><input type="hidden" name="page" value="ta-admin-cooperation-report"><label>ترم<select name="term_id"><?php foreach($terms as $t): ?><option value="<?= (int)$t->id ?>" <?= selected($term_id,$t->id,false) ?>><?= esc_html($t->name) ?></option><?php endforeach; ?></select></label><label>مسیر همکاری<select name="mode"><option value="all" <?= selected($mode_filter,'all',false) ?>>همه مسیرها</option><?php foreach($this->modes as $k=>$m): ?><option value="<?= esc_attr($k) ?>" <?= selected($mode_filter,$k,false) ?>><?= esc_html($m['title']) ?></option><?php endforeach; ?></select></label><label class="tacr-search">جست‌وجو<input name="s" value="<?= esc_attr($search) ?>" placeholder="نام استادیار یا کد"></label><button class="button button-primary">اعمال فیلتر</button></form>
        <div class="tacr-kpis"><div><b><?= number_format_i18n($total) ?></b><span>استادیار در گزارش</span></div><div><b><?= number_format_i18n($selected) ?></b><span>مسیر انتخاب‌شده</span></div><div><b><?= number_format_i18n($eligible) ?></b><span>واجد شرایط فعلی</span></div><div><b><?= number_format_i18n($capacity_total) ?></b><span>ظرفیت کل</span></div><div><b><?= number_format_i18n($capacity_used) ?></b><span>ظرفیت استفاده‌شده</span></div></div>
        <div class="tacr-table-wrap"><table class="widefat striped"><thead><tr><th>استادیار</th><th>مسیر همکاری</th><th>تعهد</th><th>تعداد هنرجو</th><th>امتیاز بار</th><th>شرط مسیر</th><th>ظرفیت کل</th><th>استفاده‌شده</th><th>باقی‌مانده</th><th>وضعیت</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="10" class="tacr-empty">داده‌ای برای این فیلتر یافت نشد.</td></tr><?php endif; foreach($rows as $r): ?><tr><td><strong><?= esc_html($r['name']) ?></strong><small><?= esc_html($r['code']?:'بدون کد') ?></small></td><td><?php if($r['mode_data']): ?><strong class="tacr-mode mode-<?= esc_attr($r['mode']) ?>"><?= esc_html($r['mode_data']['title']) ?></strong><small><?= esc_html($r['mode_data']['name']) ?></small><?php else: ?><span class="tacr-muted">انتخاب نشده</span><?php endif; ?></td><td><?php if(in_array($r['mode'],['development','capacity'],true)): ?><?= $r['commitment']?'✅ پذیرفته شده':'❌ پذیرفته نشده' ?><?php else: ?><span class="tacr-muted">موضوعیتی ندارد</span><?php endif; ?></td><td><?= number_format_i18n($r['student_count']) ?></td><td><?= number_format_i18n($r['load_score']) ?></td><td><?= $r['mode_data']?number_format_i18n($r['mode_data']['count']).' / '.number_format_i18n($r['mode_data']['score']):'—' ?></td><td><?= number_format_i18n($r['capacity_total']) ?></td><td><?= number_format_i18n($r['capacity_used']) ?></td><td><?= number_format_i18n(max(0,$r['capacity_total']-$r['capacity_used'])) ?></td><td><span class="tacr-status <?= ($r['eligible']||!empty($r['exempt']))?'ok':'warn' ?>"><?= (!empty($r['exempt']) ? 'معاف از الزام در این ترم' : (($r['mode'] && !$r['eligible']) ? 'ناقص — نیازمند اصلاح' : ($r['eligible']?'واجد شرایط':'مسیر انتخاب نشده'))) ?></span></td></tr><?php endforeach; ?></tbody></table></div>
        <h2 class="tacr-section-title">جزئیات ظرفیت به تفکیک استادیار</h2><div class="tacr-detail-grid"><?php foreach($rows as $r): ?><details class="tacr-detail"><summary><span><?= esc_html($r['name']) ?></span><b><?= esc_html($r['mode_data']['title']??'مسیر انتخاب نشده') ?></b><i><?= count($r['capacities']) ?> ردیف</i></summary><div class="tacr-detail-body"><div class="tacr-mini-grid"><div><b><?= number_format_i18n($r['student_count']) ?></b><span>هنرجوی اصلی</span></div><div><b><?= number_format_i18n($r['load_score']) ?></b><span>امتیاز بار آموزشی</span></div><div><b><?= number_format_i18n($r['capacity_total']) ?></b><span>ظرفیت کل</span></div><div><b><?= number_format_i18n($r['capacity_used']) ?></b><span>مصرف‌شده</span></div></div><table><thead><tr><th>دوره</th><th>جنسیت</th><th>پیام‌رسان</th><th>کل</th><th>مصرف</th><th>باقی‌مانده</th><th>عملیات</th></tr></thead><tbody><?php foreach($r['capacities'] as $c): ?><tr><td><?= esc_html($this->courses[$c->course_type]??$c->course_type) ?></td><td><?= esc_html(['male'=>'آقایان','female'=>'خانم‌ها','both'=>'هر دو'][$c->student_gender]??$c->student_gender) ?></td><td><?= esc_html(['telegram'=>'تلگرام','bale'=>'بله','eitaa'=>'ایتا','both'=>'فرقی ندارد'][$c->messenger]??$c->messenger) ?></td><td><?= (int)$c->total_capacity ?></td><td><?= (int)$c->used_capacity ?></td><td><?= max(0,(int)$c->total_capacity-(int)$c->used_capacity) ?></td><td><?php if((int)$c->used_capacity===0): ?><button type="button" class="button button-small button-link-delete tacr-delete-capacity" data-capacity-id="<?= (int)$c->id ?>">🗑 حذف</button><?php else: ?><span class="tacr-no-delete">🔒 استفاده‌شده</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></details><?php endforeach; ?></div>
        <script>jQuery(function($){$(document).on('click','.tacr-delete-capacity',function(){var b=$(this),id=b.data('capacity-id');if(!window.confirm('این ردیف ظرفیت حذف شود؟'))return;b.prop('disabled',true).text('⏳');$.post(ajaxurl,{action:'ta_admin_delete_report_capacity',nonce:'<?= esc_js(wp_create_nonce('ta_admin_cooperation_report')) ?>',capacity_id:id}).done(function(r){if(r.success){b.closest('tr').fadeOut(220,function(){$(this).remove()});}else{alert(r.data&&r.data.message?r.data.message:'حذف انجام نشد.');b.prop('disabled',false).text('🗑 حذف');}}).fail(function(){alert('ارتباط با سرور برقرار نشد.');b.prop('disabled',false).text('🗑 حذف');});});});</script><style>.ta-admin-coop-report{max-width:1500px}.tacr-head{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:25px 30px;margin:20px 0;background:linear-gradient(135deg,#171b3a,#3730a3);border-radius:18px;color:#fff}.tacr-head span{color:#c7d2fe}.tacr-head h1{color:#fff!important;margin:8px 0;font-size:25px}.tacr-head p{color:#dbe2ff;margin:0}.tacr-export{background:#fff;color:#3730a3;text-decoration:none;padding:11px 16px;border-radius:10px;font-weight:700;white-space:nowrap}.tacr-filters{display:flex;align-items:end;gap:12px;flex-wrap:wrap;background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:16px;margin-bottom:16px}.tacr-filters label{display:flex;flex-direction:column;gap:5px;font-weight:700;font-size:12px}.tacr-filters select,.tacr-filters input{min-width:180px;padding:8px;border:1px solid #cbd5e1;border-radius:7px}.tacr-search{flex:1}.tacr-search input{width:100%}.tacr-kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:18px}.tacr-kpis>div,.tacr-mini-grid>div{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:15px}.tacr-kpis b,.tacr-mini-grid b{display:block;color:#4338ca;font-size:23px}.tacr-kpis span,.tacr-mini-grid span{color:#64748b;font-size:11px}.tacr-table-wrap{background:#fff;border:1px solid #e5e7eb;border-radius:14px;overflow:auto}.tacr-table-wrap table{min-width:1100px}.tacr-table-wrap td small,.tacr-detail summary b,.tacr-detail summary i{display:block;color:#64748b;font-size:11px;margin-top:4px}.tacr-mode{color:#4338ca}.tacr-muted{color:#94a3b8}.tacr-no-delete{color:#94a3b8;font-size:11px}.tacr-status{display:inline-block;border-radius:99px;padding:5px 9px;font-size:11px;font-weight:700}.tacr-status.ok{background:#dcfce7;color:#166534}.tacr-status.warn{background:#fef3c7;color:#92400e}.tacr-empty{text-align:center;padding:30px!important}.tacr-section-title{margin-top:28px}.tacr-detail-grid{display:grid;gap:10px}.tacr-detail{background:#fff;border:1px solid #e5e7eb;border-radius:12px;overflow:hidden}.tacr-detail summary{display:grid;grid-template-columns:1fr 1fr auto;gap:12px;align-items:center;padding:14px 16px;cursor:pointer;font-weight:700}.tacr-detail summary b{margin:0;color:#4338ca}.tacr-detail summary i{margin:0;font-style:normal}.tacr-detail-body{border-top:1px solid #e5e7eb;padding:15px;overflow:auto}.tacr-mini-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:14px}.tacr-detail-body table{width:100%;border-collapse:collapse;font-size:12px}.tacr-detail-body th,.tacr-detail-body td{padding:9px;border-bottom:1px solid #edf0f5;text-align:right}@media(max-width:900px){.tacr-head{display:block}.tacr-export{display:inline-block;margin-top:15px}.tacr-kpis{grid-template-columns:repeat(2,1fr)}.tacr-mini-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.tacr-kpis{grid-template-columns:1fr}.tacr-filters label,.tacr-filters select,.tacr-filters input{width:100%}.tacr-detail summary{grid-template-columns:1fr}.tacr-detail summary i{display:none}}</style></div>
        <?php
    }
    private function build_rows( int $term_id ): array {
        // گزارش جامع فقط استادیارهای فعال را نمایش می‌دهد.
        $assistants=TA_Database::get_results('SELECT * FROM '.TA_Database::table('assistants').' WHERE is_active = 1 ORDER BY id ASC'); $rows=[]; $cap_table=TA_Database::table('capacities'); $weights=['creative'=>1,'basic_writing'=>1.5,'intro'=>2,'advanced'=>3,'ladder'=>0.5];
        foreach($assistants as $ta){$user=get_user_by('id',(int)$ta->user_id);$caps=$term_id?TA_Database::get_results("SELECT * FROM {$cap_table} WHERE ta_id=%d AND term_id=%d ORDER BY course_type,student_gender,messenger",[$ta->id,$term_id]):[];$total=0;$used=0;$students=0;$score=0;foreach($caps as $c){$total+=(int)$c->total_capacity;$used+=(int)$c->used_capacity;if(isset($weights[$c->course_type])){$students+=(int)$c->total_capacity;$score+=(int)$c->total_capacity*$weights[$c->course_type];}}$setting=get_option('ta_cooperation_'.(int)$ta->id.'_'.$term_id,['mode'=>'','commitment'=>0]);$mode=$setting['mode']??'';$has_pro=false;$has_crit=false;$has_other=false;foreach($caps as $c){if((int)$c->total_capacity<=0)continue;if($c->course_type==='professional')$has_pro=true;elseif($c->course_type==='critique')$has_crit=true;else $has_other=true;}if(!$has_other&&($has_pro||$has_crit)&&!in_array($mode,['educational','development','capacity'],true))$mode=$has_pro&&$has_crit?'professional_critique':($has_pro?'professional':'critique');$md=$this->modes[$mode]??null;$eligible=false;if($md){$eligible=in_array($mode,['professional','critique','professional_critique'],true)?true:($students >= $md['count'] && $score >= $md['score']);if($mode==='capacity'){$pre=0;foreach($caps as $c)if($c->course_type==='intro')$pre+=(int)$c->total_capacity;$adv=$this->course_count($caps,'advanced');$eligible=$adv>=20||($students>=32&&$score>=57&&($pre>=12||$adv>=12));}if(($setting['status']??'complete')==='incomplete')$eligible=false;}$raw_commitment=strtolower(trim((string)($setting['commitment']??'')));$commitment=in_array($mode,['development','capacity'],true)&&in_array($raw_commitment,['1','true','yes','on'],true);$coop_required=(bool)get_option('ta_term_require_cooperation_'.(int)$term_id,1);$rows[]=['exempt'=>!$coop_required,'name'=>$user?$user->display_name:'کاربر حذف‌شده','code'=>$ta->ta_code,'mode'=>$mode,'mode_data'=>$md,'commitment'=>$commitment,'student_count'=>$students,'load_score'=>$score,'capacity_total'=>$total,'capacity_used'=>$used,'capacities'=>$caps,'eligible'=>$eligible];}return $rows;
    }
    private function course_count(array $caps,string $type):int{$n=0;foreach($caps as $c)if($c->course_type===$type)$n+=(int)$c->total_capacity;return $n;}
    private function export_csv(): void {if(!current_user_can('manage_options')||!isset($_GET['_wpnonce'])||!wp_verify_nonce($_GET['_wpnonce'],'ta_export_cooperation_report'))wp_die('دسترسی غیرمجاز');$rows=$this->build_rows(absint($_GET['term_id']??0));nocache_headers();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename=ta-cooperation-report.csv');echo "\xEF\xBB\xBF"; $out=fopen('php://output','w');fputcsv($out,['استادیار','کد','مسیر همکاری','تعهد','تعداد هنرجو','امتیاز بار آموزشی','ظرفیت کل','استفاده‌شده','باقی‌مانده','وضعیت']);foreach($rows as $r)fputcsv($out,[$r['name'],$r['code'],$r['mode_data']['title']??(($r['mode']??'')==='professional'?'نویسندگی حرفه‌ای':((($r['mode']??'')==='critique')?'نقد اثر':((($r['mode']??'')==='professional_critique')?'نویسندگی حرفه‌ای و نقد اثر':'مسیر انتخاب نشده'))),$r['commitment']?'بله':'خیر',$r['student_count'],$r['load_score'],$r['capacity_total'],$r['capacity_used'],max(0,$r['capacity_total']-$r['capacity_used']),!empty($r['exempt'])?'معاف از الزام':($r['eligible']?'واجد شرایط':'نیازمند بررسی')]);fclose($out);exit;}
}
